python3 -I -c 'O=None;S="import sys,json\ndef J(x):return json.dumps(x,separators=(\",\",\":\"),sort_keys=True)\ndef G(b):\n n=1\n for x in b:n=n*257+x+1\n return hex(n)[2:]\ndef D(g):\n n=int(g,16);b=[]\n while n>1:n,x=divmod(n-1,257);b.append(x)\n assert n==1;return bytes(b[::-1])\ndef Q(o):\n q=chr(39);return \"python3 -I -c \"+q+\"O=\"+str(o).replace(\" \",\"\")+\";S=\"+J(S)+\";exec(S)\"+q+\" \"+chr(34)+\"$@\"+chr(34)+chr(10)\nm,*v=sys.argv[1:] or [\"solve\" if O is None else \"apply\"]\nif m==\"solve\":\n f,s,r=(v+[\"UO.sh\",\"[[0,1],[1,3],[2,5]]\",4][len(v):]);s=json.loads(s);r=int(r);assert 0<=r<=32 and 1<len(s)<=64 and all(len(z)==2 and all(type(i)==int for i in z) for z in s)\n h=range(-r,r+1);L=lambda o:sum((o[0]*x+o[1]-y)**2 for x,y in s);q=min(((a,b) for a in h for b in h),key=lambda o:(L(o),sum(map(abs,o)),o));e=L(q)\n if e:sys.exit(f\"EXHAUSTED {e}\")\n t=Q(q).encode();assert len(t)<=2048 and D(G(t))==t\n with open(f,\"xb\") as w:w.write(t)\n print(J(dict(status=\"SOLVED\",operator=q,bytes=len(t))))\nelif m==\"apply\":assert O is not None;print(O[0]*int(v[0] if v else 10)+O[1])\nelif m==\"encode\":print(G(Q(O).encode()))\nelif m==\"decode\":sys.stdout.buffer.write(D(v[0]))\nelse:\n assert m in (\"tm\",\"resume\");a=json.loads(D(v[0]) if m==\"resume\" else v[0]);n=int(v[1]);assert 0<=n<=100000\n if m==\"tm\":a.update(s=a[\"start\"],p=0,k=0,t={str(i):x for i,x in enumerate(a.get(\"input\",\"\")) if x!=\"_\"})\n s,p,k,t=[a[i] for i in (\"s\",\"p\",\"k\",\"t\")];d={}\n for q,c,u,w,j in a[\"rules\"]:\n  assert all(type(x)==str for x in (q,c,u,w)) and len(c)==len(w)==1 and type(j)==int and j in (-1,0,1) and (q,c) not in d;d[q,c]=(u,w,j)\n for _ in range(n):\n  z=(s,t.get(str(p),\"_\"))\n  if s in a[\"halt\"] or z not in d:break\n  s,w,j=d[z];t.pop(str(p),None) if w==\"_\" else t.__setitem__(str(p),w);p+=j;k+=1\n a.update(s=s,p=p,k=k,t=t);print(J(dict(status=\"HALTED\" if s in a[\"halt\"] or (s,t.get(str(p),\"_\")) not in d else \"UNKNOWN\",state=a,checkpoint=G(J(a).encode()))))";exec(S)' "$@"
